content.css:
#my_dataviz {
  max-height: calc(100% - 10px);
  overflow-y: auto;
  height: 100%;
}
.hidden-search {
  display: none !important;
}
li[data-parent].closed {
  display: none !important;
}
li[data-parent].open:not(.hidden-search) {
  display: block !important;
}
.vsb-menu {
  cursor: pointer;
  z-index: 1000;
  display: none;
  position: absolute;
  /*Don't change*/
  border: 1px solid #B2B2B2;
  background-color: #FFFFFF;
  background-clip: padding-box;
  border: 1px solid rgba(0, 0, 0, 0.15);
  border-radius: 4px;
  font-size: 11px;
  width: 100%;
}
.vsb-js-search-zone {
  z-index: 1001;
  min-height: 1.8em;
  padding: 2px 10px;
  background-color: #FFFFFF;
  left: 0;
  right: 0;
  margin: 2px;
}
.vsb-js-search-zone input {
  border: 1px solid grey;
  margin-left: 0px;
  width: calc(100% - 10px);
  border-radius: 4px;
  height: 25px !important;
}
.vsb-main {
  position: relative;
  /*Don't change*/
  display: inline-block;
  vertical-align: bottom;
  text-align: left;
  flex: 1;
}
.vsb-menu li:hover {
  background: linear-gradient(#F5F5F5, #E8E8E8);
}
.vsb-menu ul {
  user-select: none;
  list-style: none;
  white-space: nowrap;
  margin: 0px;
  margin-top: 4px;
  padding-left: 10px;
  padding-right: 10px;
  padding-bottom: 3px;
  color: #333333;
  cursor: pointer;
  overflow-y: auto;
  max-width: 100%;
}
li.disabled {
  cursor: not-allowed;
  opacity: 0.3;
  background-color: #999999;
}
li.overflow {
  background-color: #999999;
}
li.short {
  overflow: hidden;
  text-overflow: ellipsis;
}
.vsb-main button {
  min-width: 120px;
  border-radius: 0;
  width: 100%;
  text-align: left;
  z-index: 1;
  color: #333333;
  background: white !important;
  border: 1px solid rgba(0, 0, 0, 0.15) !important;
  line-height: 20px;
  font-size: 14px;
  padding: 6px 12px;
  height: 40px;
}
.vsb-main button.disabled {
  cursor: not-allowed;
  opacity: 0.65;
}
.vsb-main .title {
  margin-right: 6px;
  user-select: none;
}
.vsb-main li:hover {
  background: linear-gradient(#F5F5F5, #E8E8E8);
}
.vsb-main ul {
  white-space: nowrap;
}
.vsb-menu li {
  font-size: 14px;
  background-color: #FFFFFF;
  min-height: 1.4em;
  padding: 0.2em 2em 0.2em 1em;
}
.vsb-menu li.grouped-option b {
  display: inline-block;
  font-size: 15px;
  margin-left: 15px;
  transform: translate(-18px);
}
.vsb-menu .single li.grouped-option b {
  margin-left: 7px;
}
.vsb-menu li.grouped-option.open span {
  display: inline-block;
  font-size: inherit;
  height: 8px;
  width: 8px;
  transform: translate(-38px) rotate(45deg);
  border-bottom: 2px solid black;
  border-right: 2px solid black;
  border-radius: 0px;
  position: absolute;
  left: 41px;
  top: 10px;
}
.vsb-menu li.grouped-option.closed span {
  display: inline-block;
  font-size: inherit;
  height: 8px;
  width: 8px;
  transform: translate(-38px) rotate(-45deg);
  border-bottom: 2px solid black;
  border-right: 2px solid black;
  border-radius: 0px;
  position: absolute;
  left: 38px;
  top: 10px;
}
.vsb-menu li.grouped-option i {
  display: inline-block;
  font-size: inherit;
  float: left;
  font-weight: bold;
  left: -12px;
  height: 16px;
  width: 16px;
  border: 1px solid;
  margin-top: 0px;
  color: black;
  top: 5px;
  position: relative;
}
.vsb-menu .single li.grouped-option i {
  display: none;
}
.vsb-menu li.grouped-option.checked i::after {
  content: '';
  font-size: inherit;
  color: #333333;
  float: left;
  display: inline-block;
  height: 13px;
  width: 13px;
  position: absolute;
  background: #000000;
  left: 1.5px;
  top: 1.5px;
}
.vsb-menu :not(.multi) li.active {
  margin-left: 7px;
}
.vsb-menu :not(.multi) li.active::before {
  content: '';
  display: inline-block;
  font-size: inherit;
  margin-left: -18px;
  transform: rotate(45deg);
  height: 10px;
  width: 5px;
  border-bottom: 3px solid black;
  border-right: 3px solid black;
  border-radius: 2px;
}
.vsb-menu .multi li {
  font-size: 14px;
  background-color: #FFFFFF;
  min-height: 1.4em;
  padding: 0.2em 2em 0.2em 26px;
  line-height: 26px;
  position: relative;
}
.vsb-menu .multi li.grouped-option {
  font-size: 15px;
  padding-left: 34px;
}
.vsb-menu .multi li.grouped-option:hover {
  font-weight: bold;
  text-decoration: underline;
  color: #341f70;
}
.vsb-menu .multi li:not(.grouped-option)::before {
  content: '';
  display: inline-block;
  font-size: inherit;
  float: left;
  font-weight: bold;
  margin-right: 12px;
  border: 1px solid;
  color: black;
  width: 16px;
  height: 16px;
  position: absolute;
  left: 1px;
  top: 6px;
}
.vsb-menu .multi.single li:not(.grouped-option)::before {
  border-radius: 100%;
  top: 8px;
}
.vsb-menu .multi li:not(.grouped-option).active::after {
  content: '';
  font-size: inherit;
  background-color: #333333;
  float: left;
  display: inline-block;
  height: 14px;
  width: 14px;
  position: absolute;
  left: 3px;
  top: 8px;
}
.vsb-menu .multi.single li:not(.grouped-option).active::after {
  top: 10px;
  border-radius: 100%;
  left: 3px;
}
.caret {
  display: inline-block;
  font-size: inherit;
  height: 8px;
  width: 8px;
  border-radius: 0px;
  margin-left: 2px;
  transition: all 0.1s ease;
}
.caret.open {
  transform: translate(5px, 0px) rotate(45deg);
  border-top: 2px solid black;
  border-left: 2px solid black;
}
.caret.close {
  transform: translate(5px, -4px) rotate(45deg);
  border-bottom: 2px solid black;
  border-right: 2px solid black;
}
li[data-parent] {
  padding-left: 50px !important;
}
.vsb-menu .grouped-option ~ li {
  margin-right: 15px;
}
.vsb-menu .grouped-option ~ li:not(.grouped-option)::before {
  left: 22px;
}
.vsb-menu .multi .grouped-option ~ li:not(.grouped-option).active::after {
  left: 24px;
}
.licence-btn {
  width: 40px;
  height: 40px;
  background-image: url(data:image/svg+xml;charset=utf-8;base64,);
  background-position: center;
  background-size: cover;
  margin-left: 10px;
  display: inline-block;
  position: relative;
}
.licence-btn::before {
  position: absolute;
  content: 'Buy Licence';
  right: 0;
  top: 140%;
  background: rgba(0, 0, 0, 0.8);
  color: #FFFFFF;
  font-size: 16px;
  white-space: nowrap;
  padding: 5px 10px;
  border-radius: 4px;
  display: none;
}
.licence-btn:hover::before {
  display: block;
}
.vsb-main-container {
  display: flex;
  align-items: center;
  padding: 10px 20px 0;
}


